const escape = value => String(value).replace(/[&<>"']/g, char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
export function renderPage({games,events,minigames=[],externalGames=[]}) {
  const fighter=externalGames.filter(e=>e.release?.production===true);
  if(fighter.length>1)throw new Error('Only one approved external entry');
  for(const e of fighter)if(e.id!=='taiwanfighter'||e.href!=='https://taiwanfighter.playformosa.workers.dev/'||e.image!=='/assets/portal-taiwanfighter.webp'||e.logo!=='/assets/portal-taiwanfighter-logo.webp')throw new Error('Unapproved Fighter destination or asset');
  const externalSection=fighter.map(e=>`<section class="portal-section" id="big-games" aria-labelledby="fighter-title"><p class="eyebrow">INDEPENDENT WORLDS</p><h2 id="fighter-title">大遊戲</h2><article class="portal-card portal-card--taiwanfighter" data-external-id="taiwanfighter"><div class="portal-art"><img src="${escape(e.image)}" alt="" width="1672" height="941" loading="lazy"><img class="portal-game-logo" src="${escape(e.logo)}" alt="" width="1446" height="1120" loading="lazy"><span class="portal-art-label">${escape(e.eyebrow)}</span></div><div class="portal-card-body"><p class="portal-genre">${escape(e.genre)}</p><h3>${escape(e.title)}</h3><p class="portal-description">${escape(e.description)}</p><div class="portal-card-bottom"><span class="portal-destination">獨立遊戲網站・另開新分頁</span><a class="button portal-cta" href="${escape(e.href)}" target="_blank" rel="noopener noreferrer" aria-label="前往遊玩：${escape(e.title)}（另開新分頁）">前往遊玩 ↗</a></div></div></article></section>`).join('');
  const available=games.filter(game=>game.status==='available');
  for (const game of available) if (!/^\/games\/[a-z0-9-]+\/$/.test(game.href)) throw new Error('Expected a local game route');
  for(const game of available)if(game.image&&game.image!=='/assets/hurdles-card.png')throw new Error('Expected a local card image');
  const availableMinigames=minigames.filter(game=>game.status==='available');
  const approvedMinigames={
    'reaction-rod':['/games/reaction-rod/','/assets/reaction-rod-card.png'],
    'fast-hands':['/games/fast-hands/?intro=1','/assets/fast-hands-card-v2.webp'],
    'fast-hands-catch':['/games/fast-hands/catch.html?intro=1','/games/fast-hands/assets/intro-catch-generated.webp'],
    'fast-hands-duel':['/games/fast-hands/duel.html?intro=1','/games/fast-hands/assets/intro-duel-generated.webp']
  };
  for(const game of availableMinigames){const approved=approvedMinigames[game.id];if(!approved||game.href!==approved[0]||game.image!==approved[1])throw new Error('Unapproved minigame');}
  const nextEvents=events.filter(event=>!available.some(game=>game.event===event));
  const featured=available[0];
  const renderCard=(game,collection)=>`<article class="game-card"><a href="${escape(game.href)}" class="game-thumbnail" tabindex="-1" aria-hidden="true"><img src="${escape(game.image || "/assets/hero-long-jump.png")}"${game.image ? (game.imageStyle==='illustration' ? ' class="game-illustration"' : ' class="game-scene"') : ''} alt="" width="1536" height="1024" loading="lazy"><span>${escape(collection)} · ${escape(game.event)}</span></a><div class="game-info"><p class="game-kicker">${escape(game.kicker || "第一個挑戰，先落地再說。")}</p><h3>${escape(game.title)}</h3><p class="event-label">${escape(game.event)}${game.label ? ` · ${escape(game.label)}` : ""}</p><p class="input-chip"><span aria-hidden="true">⌨ / ☝</span> ${escape(game.input || "鍵盤／觸控")}</p>${['reaction-rod','fast-hands','fast-hands-catch','fast-hands-duel'].includes(game.id)?`<p class="play-count" title="本功能啟用後累計的開局紀錄" data-play-count="${escape(game.id)}" aria-live="polite">遊玩次數讀取中…</p>`:''}</div><a class="button button-primary game-cta" href="${escape(game.href)}" aria-label="開始挑戰：${escape(game.title)}">開始挑戰 <span aria-hidden="true">↗</span></a></article>`;
  return `<!doctype html>
